/* 履历与追溯：只读来源数据，Bootstrap 控件，三个页签各自保留筛选。 */
window.EamArchiveTraceView=(()=>{
 const states=new WeakMap(),r=EamArchiveTraceRules;
 const el=(tag,text,cls='')=>{const n=document.createElement(tag);n.textContent=text;n.className=cls;return n;};
 const button=(label,action,cls='btn btn-sm btn-outline-secondary')=>{const n=el('button',label,cls);n.type='button';n.onclick=action;return n;};
 function state(host,mode,message,retry){host.replaceChildren(el('p',message||'正在读取来源记录…','alert '+(mode==='error'?'alert-danger':'alert-secondary')));if(retry)host.append(button('重新读取',retry));}
 function render(host,rows,domain,options){
  const s=states.get(host)||{view:domain==='history'?'timeline':'list',scope:'pending',query:'',type:'',actor:'',field:'',from:'',to:'',page:1};states.set(host,s);host.replaceChildren();
  const redraw=()=>render(host,rows,domain,options),nav=el('div','','nav nav-pills gap-2 mb-3');
  const choices=domain==='history'?[['timeline','时间线'],['list','清单']]:domain==='related'?[['pending','未结事项'],['all','全部关联']]:[];
  for(const [key,label]of choices){const active=domain==='related'?s.scope:s.view;const b=button(label,()=>{if(domain==='related')s.scope=key;else s.view=key;s.page=1;redraw();},'nav-link'+(active===key?' active':''));b.setAttribute('aria-pressed',String(active===key));nav.append(b);}host.append(nav);
  host.append(el('p',domain==='history'?'业务事件按发生时间倒序；普通字段修改请查看变更审计。':domain==='related'?'按来源引用连接业务对象；对象数量不等于独立问题数量。未结状态未知的记录请在全部关联中核对。':'只读操作追溯；未提供前后值的记录不能还原字段差异。','small text-secondary'));
  const form=el('div','','d-flex flex-wrap gap-2 align-items-end mb-3');
  function input(key,label,type='text'){const wrap=el('label',label,'small d-flex flex-column gap-1'),n=document.createElement('input');n.type=type;n.value=s[key];n.className='form-control form-control-sm';n.setAttribute('aria-label',label);n.dataset.traceFilter=key;wrap.append(n);form.append(wrap);}
  input('query','搜索记录');if(domain==='audit'){input('actor','操作者');input('field','变更字段');}
  const wrap=el('label',domain==='related'?'对象类型':'来源类型','small d-flex flex-column gap-1'),select=document.createElement('select');select.className='form-select form-select-sm';select.setAttribute('aria-label',wrap.textContent);select.dataset.traceFilter='type';select.append(new Option('全部类型',''));for(const type of [...new Set(rows.map(row=>row.objectType||row.source||'未记录'))])select.append(new Option(type,type));select.value=s.type;wrap.append(select);form.append(wrap);
  input('from','起始日期','date');input('to','结束日期','date');form.append(button('应用筛选',()=>{for(const n of form.querySelectorAll('[data-trace-filter]'))s[n.dataset.traceFilter]=n.value.trim();s.page=1;redraw();},'btn btn-sm btn-primary'),button('重置筛选',()=>{for(const key of ['query','type','actor','field','from','to'])s[key]='';s.page=1;redraw();}),button('刷新来源',options.refresh));host.append(form);
  let selected;try{selected=r.filter(rows,s).filter(row=>domain!=='related'||s.scope==='all'||row.isPending===true).sort((a,b)=>(r.time(b.eventAt||b.updatedAt)||0)-(r.time(a.eventAt||a.updatedAt)||0));}catch(error){host.append(el('p',error.message,'alert alert-danger'));return;}
  const groups=domain==='related'?r.groups(rows):[],groupMap=new Map();groups.forEach((g,i)=>g.forEach(row=>groupMap.set(row,i+1)));
  host.append(el('p','当前范围 '+selected.length+' 条'+(domain==='related'?' · 涉及 '+new Set(selected.map(row=>groupMap.get(row))).size+' 个来源关系组':''),'small fw-semibold'));
  const pages=Math.max(1,Math.ceil(selected.length/8));s.page=Math.min(s.page,pages);const page=selected.slice((s.page-1)*8,s.page*8);
  function actions(row,parent){parent.append(button('详情',()=>options.openRecord({...row,detailSections:[...(row.detailSections||[]),{title:domain==='history'?'事件与影响':domain==='related'?'来源关系':'操作依据',fields:[['操作者 / 责任人',row.actor||row.owner||row.assignee||row.executor],['发生 / 操作时间',row.eventAt||row.updatedAt],['来源对象',row.sourceId||row.objectId],['原因 / 证据',row.reason||row.evidence],['设备影响',row.impact],['来源版本',row.revision===undefined?'未记录':String(row.revision)],['前后状态',r.diff(row.before,row.after).map(x=>x.field+'：'+x.before+' → '+x.after).join('；')],['关联引用',r.refs(row).map(x=>(x.kind||'对象')+' / '+x.id).join('；')]]}]},domain)));if(row.target)parent.append(button('打开来源',()=>Eam.go(row.target,row.query)));else parent.append(el('span','来源入口未提供','small text-secondary ms-2'));}
  if(domain==='history'&&s.view==='timeline'){const list=el('ol','','list-group list-group-flush');list.setAttribute('aria-label','生命周期时间线');for(const row of page){const item=el('li','','list-group-item border-start border-primary');item.append(el('p',(row.eventAt||row.updatedAt||'未记录')+' · '+(row.actor||row.owner||'责任人未记录'),'small text-secondary mb-1'),el('h3',row.name,'h6'),el('p',row.impact||row.content||'设备影响未记录','small'),el('p','来源 '+(row.sourceId||row.objectId||'未记录')+' · '+(row.source||'未记录'),'small'));actions(row,item);list.append(item);}host.append(list);}
  else {const region=el('div','','table-responsive'),table=el('table','','table table-sm align-middle');table.setAttribute('aria-label',domain==='audit'?'变更审计清单':domain==='related'?'关联业务清单':'生命周期清单');const columns=domain==='audit'?[['eventAt','操作时间'],['name','动作'],['actor','操作者'],['sourceId','来源对象']]:domain==='related'?[['group','关系组'],['objectType','对象类型'],['name','对象'],['status','状态'],['owner','责任人'],['dueAt','期限'],['links','关联引用']]:[['eventAt','事件时间'],['name','业务事件'],['actor','责任人'],['impact','设备影响'],['sourceId','来源单据']];const head=el('thead',''),tr=el('tr','');for(const [,label]of columns)tr.append(el('th',label));tr.append(el('th','操作'));head.append(tr);table.append(head);const body=el('tbody','');for(const row of page){const tr=el('tr','');for(const [key]of columns){const v=key==='group'?'组 '+groupMap.get(row):key==='links'?r.refs(row).map(x=>(x.kind||'对象')+' / '+x.id).join('；'):key==='eventAt'?row.eventAt||row.updatedAt:key==='actor'?row.actor:key==='owner'?row.owner||row.assignee||row.executor:row[key];tr.append(el('td',v===undefined||v===null||v===''?'未记录':String(v),'text-break'));}const td=el('td','','text-nowrap');actions(row,td);if(domain==='audit')td.append(button('字段差异',()=>td.querySelector('button').click()));tr.append(td);body.append(tr);}table.append(body);region.append(table);host.append(region);}
  if(!selected.length)host.append(el('p','当前条件没有记录；可重置筛选或查看全部来源。','alert alert-secondary'));
  const footer=el('div','','mt-3');EamUiComponents.pagination(footer,{page:s.page,pages,total:selected.length,pageSize:8,onChange:page=>{s.page=page;redraw();}});host.append(footer);
 }
 return {render,state};
})();
